fun stretch(input: Int): Int {
    var total = input
    val a = total + 1
    val b = a + 1
    val c = b + 1
    val d = c + 1
    val e = d + 1
    val f = e + 1
    val g = f + 1
    val h = g + 1
    val i = h + 1
    val j = i + 1
    val k = j + 1
    val m = k + 1
    val n = m + 1
    val o = n + 1
    val p = o + 1
    total += p
    return total
}
